import pyomo.environ as pyo

DATA = {
    "foods": ["Chicken", "Tofu", "Rice", "Avocado"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Chicken": 3,
        "Tofu": 6,
        "Rice": 1,
        "Avocado": 10,
    },
    "content": {
        # nutrient -> food -> amount per serving
        "protein":  {"Chicken": 2,  "Tofu": 18, "Rice": 2,  "Avocado": 18},
        "carbs":    {"Chicken": 4,  "Tofu": 17, "Rice": 28, "Avocado": 27},
        "calories": {"Chicken": 218, "Tofu": 290, "Rice": 298, "Avocado": 158},
    },
    "requirement": {
        "protein": 86,
        "carbs": 120,
        "calories": 2435,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: servings of each food (continuous, non-negative)
    model.servings = pyo.Var(
        model.FOODS,
        within=pyo.NonNegativeReals,
        bounds=(0, None),
    )

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.servings[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Nutrient requirements: each nutrient intake >= requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.servings[i] for i in m.FOODS) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model

